pub struct Url {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl Url {
    pub fn from_components(
        scheme: String,
        host: String,
        port: i32,
        path: String,
        query: String,
        fragment: String,
    ) -> Self {
        Self {
            scheme: scheme.to_ascii_lowercase(),
            host,
            port: normalize_port(port),
            path: normalize_path(path),
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn to_string(&self) -> String {
        let mut output = String::new();

        if self.scheme.is_empty() {
            output.push_str(&self.path);
        } else {
            output.push_str(&self.scheme);
            output.push_str("://");
            output.push_str(&self.host);
            if self.port != -1 {
                output.push(':');
                output.push_str(&self.port.to_string());
            }
            output.push_str(&self.path);
        }

        if !self.query.is_empty() {
            output.push('?');
            output.push_str(&self.query);
        }

        if !self.fragment.is_empty() {
            output.push('#');
            output.push_str(&self.fragment);
        }

        output
    }

    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

fn normalize_port(port: i32) -> i32 {
    if (0..=65535).contains(&port) {
        port
    } else {
        -1
    }
}

fn normalize_path(path: String) -> String {
    if path.is_empty() || path.starts_with('/') {
        path
    } else {
        format!("/{path}")
    }
}

#[cfg(test)]
mod tests {
    use super::Url;

    #[test]
    fn normalizes_components_like_the_binary() {
        let url = Url::from_components(
            "HTTP".to_string(),
            "Example.COM".to_string(),
            65536,
            "path".to_string(),
            "q=1".to_string(),
            "frag".to_string(),
        );

        assert_eq!(url.scheme(), "http");
        assert_eq!(url.host(), "Example.COM");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "/path");
        assert_eq!(url.to_string(), "http://Example.COM/path?q=1#frag");
        assert!(url.is_valid());
    }

    #[test]
    fn scheme_less_urls_ignore_host_and_port_in_string_form() {
        let url = Url::from_components(
            String::new(),
            "example.com".to_string(),
            80,
            String::new(),
            "q=1".to_string(),
            "frag".to_string(),
        );

        assert_eq!(url.to_string(), "?q=1#frag");
        assert!(url.is_valid());
    }

    #[test]
    fn empty_host_and_empty_path_are_invalid() {
        let url = Url::from_components(
            "http".to_string(),
            String::new(),
            80,
            String::new(),
            String::new(),
            String::new(),
        );

        assert_eq!(url.to_string(), "http://:80");
        assert!(!url.is_valid());
    }
}

